const DAY=86400000;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(value,options)=>new Intl.DateTimeFormat('en-US',{timeZone:'UTC',...options}).format(value);
const time=value=>date(value,{hour:'numeric',minute:'2-digit'});
function monday(value){const d=new Date(value);return Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())-((d.getUTCDay()+6)%7)*DAY;}
export function setupCalendar(getState){
 const dialog=document.createElement('dialog');dialog.className='appointment-calendar';dialog.setAttribute('aria-labelledby','calendar-title');document.body.append(dialog);
 let week=0,provider='all',selected=null,opener=null;
 const appointments=()=>getState().cases.filter(c=>c.appointment).map(c=>({...c.appointment,patient:c.name,treatment:c.treatment,patientId:c.id,completed:c.sourceStatus==='completed'})).sort((a,b)=>a.start-b.start);
 function render(){
  const all=appointments(),items=all.filter(a=>a.start>=week&&a.start<week+7*DAY&&(provider==='all'||a.provider===provider));
  const days=Array.from({length:7},(_,i)=>week+i*DAY),providers=['Dr. Lee','Dr. Shah'];
  const earliest=Math.min(8,...items.map(a=>new Date(a.start).getUTCHours())),latest=Math.max(18,...items.map(a=>Math.ceil((a.start%DAY)/3600000+(a.duration||60)/60)));
  const eventMarkup=a=>`<button type="button" class="calendar-event ${a.kind==='Discussion'?'discussion':''} ${a.completed?'completed':''}" data-calendar-patient="${esc(a.patientId)}" aria-label="${esc(a.patient)}, ${esc(a.treatment)}, ${date(a.start,{weekday:'long',month:'short',day:'numeric'})} at ${time(a.start)}"><strong>${esc(a.patient)}</strong><span>${time(a.start)} · ${a.duration} min</span><span>${esc(a.treatment)}</span></button>`;
  const today=Math.floor(getState().now/DAY)*DAY;
  const chosen=items.find(a=>a.patientId===selected);
  dialog.innerHTML=`<div class="calendar-head"><div><p class="calendar-kicker">Scheduling · appointment book</p><h2 id="calendar-title">${date(week,{month:'short',day:'numeric'})} – ${date(week+6*DAY,{month:'short',day:'numeric',year:'numeric'})}</h2></div><button class="calendar-close" data-calendar="close" aria-label="Close calendar">×</button></div><div class="calendar-toolbar"><span>${items.length} ${items.length===1?'appointment':'appointments'} · saved demo bookings</span><div><label class="sr-only" for="calendar-provider">Provider</label><select id="calendar-provider"><option value="all">All providers</option>${providers.map(p=>`<option ${p===provider?'selected':''}>${esc(p)}</option>`).join('')}</select><button class="control" data-calendar="current">Current week</button><button class="control" data-calendar="previous" aria-label="Previous week">‹</button><button class="control" data-calendar="next" aria-label="Next week">›</button></div></div><div class="calendar-week"><div class="calendar-day-head"><span></span>${days.map(d=>`<strong class="${d===today?'calendar-today':''}">${date(d,{weekday:'short'})} <span>${date(d,{day:'numeric'})}</span></strong>`).join('')}</div><div class="calendar-time-grid" style="--calendar-hours:${latest-earliest}"><div class="calendar-times">${Array.from({length:latest-earliest},(_,i)=>`<span>${time(week+(earliest+i)*3600000)}</span>`).join('')}</div>${days.map(d=>`<div class="calendar-day ${d===today?'calendar-today':''} ${new Date(d).getUTCDay()%6===0?'calendar-weekend':''}">${items.filter(a=>a.start>=d&&a.start<d+DAY).map(a=>`<div class="calendar-event-position" style="top:${((a.start-d)/3600000-earliest)*52}px;height:${Math.max(42,(a.duration||60)/60*52)}px">${eventMarkup(a)}</div>`).join('')}</div>`).join('')}</div></div><div class="calendar-agenda">${days.map(d=>{const dayItems=items.filter(a=>a.start>=d&&a.start<d+DAY);return dayItems.length?`<section><h3>${date(d,{weekday:'long',month:'short',day:'numeric'})}</h3>${dayItems.map(eventMarkup).join('')}</section>`:'';}).join('')}</div>${!items.length?'<p class="calendar-empty">No saved appointments this week.</p>':''}<div class="calendar-selection" ${chosen?'':'hidden'}>${chosen?`<strong>${esc(chosen.patient)} · ${esc(chosen.treatment)}</strong><span>${date(chosen.start,{weekday:'long',month:'short',day:'numeric'})} · ${time(chosen.start)}–${time(chosen.start+chosen.duration*60000)} · ${esc(chosen.provider)}</span><span>${chosen.completed?'Completion recorded':chosen.kind==='Discussion'?'Discussion with the dentist':'Treatment appointment'}${!chosen.completed&&chosen.start+chosen.duration*60000<getState().now?' · Past appointment; confirm outcome':''}</span>`:''}</div><div class="calendar-footer"><span><i></i>Treatment</span><span><i class="discussion-key"></i>Dentist discussion</span><small>Demo practice times · appointments outside this prototype are not shown.</small></div>`;
 }
 let startedOutside=false;
 const outside=event=>{const r=dialog.getBoundingClientRect();return event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom;};
 dialog.addEventListener('pointerdown',event=>{startedOutside=event.target===dialog&&outside(event);});
 dialog.addEventListener('pointerup',event=>{if(startedOutside&&event.target===dialog&&outside(event))dialog.close();startedOutside=false;});
 document.addEventListener('click',event=>{if(!event.target.closest('[data-open-calendar]'))return;opener=event.target.closest('[data-open-calendar]');week=monday(getState().now);provider='all';selected=null;render();dialog.showModal();});
 dialog.addEventListener('click',event=>{const item=event.target.closest('[data-calendar-patient]');if(item){selected=item.dataset.calendarPatient;render();[...dialog.querySelectorAll('[data-calendar-patient]')].find(b=>b.dataset.calendarPatient===selected&&b.getClientRects().length)?.focus({preventScroll:true});return;}const action=event.target.closest('[data-calendar]')?.dataset.calendar;if(!action)return;if(action==='close')dialog.close();else{week=action==='current'?monday(getState().now):week+(action==='next'?7:-7)*DAY;selected=null;render();dialog.querySelector(`[data-calendar="${action}"]`)?.focus();}});
 dialog.addEventListener('change',event=>{if(event.target.id==='calendar-provider'){provider=event.target.value;selected=null;render();dialog.querySelector('#calendar-provider').focus();}});
 dialog.addEventListener('close',()=>opener?.focus());
}
